    const title = A.heading(1, `<span${P('title')}>${esc(d.title)}</span>${d.title2 ? `<br><span${P('title2')}>${esc(d.title2)}</span>` : ''}`, '');
    const btn = d.cta && d.cta.href ? `<div>${A.button('primary', d.cta.label, 'cta')}</div>` : '';
    if (v === 'page') { const inner = `<div class="stack s8">${eb}${title}${d.body ? A.text('muted', d.body, 'body') : ''}</div>`; return c.nested ? inner : A.section('', inner); }
    if (v === 'title') return A.section('', `<div class="stack">${eb}${title}${d.body ? A.text('lead', d.body, 'body') : ''}${btn}</div>`, { pad: 'l', rule: true });
    if (v === 'image') return A.section('', `<div class="g2"><div class="stack">${eb}${title}${d.body ? A.text('lead', d.body, 'body') : ''}${btn}</div>${A.media('image', fileLabel(d.imageUrl), '4/3', 'imageUrl')}</div>`, { pad: 'l', rule: true });
    const bg = d.videoUrl ? 'Фон · видео · ' + fileLabel(d.videoUrl) : null;
    const tone = d.videoUrl ? 'dark' : '';
    const textCol = `<div class="stack">${eb}${title}${d.subtitle ? A.text('sub', d.subtitle, 'subtitle') : ''}${d.body ? A.text(v === 'banner' || d.subtitle ? '' : 'lead', d.body, 'body') : ''}${d.note ? A.text('small', d.note, 'note') : ''}${btn}</div>`;
    if (v === 'video') return A.section(tone, `<div class="g2">${textCol}<div></div></div>`, { pad: 'l', bg, rule: !d.videoUrl });
    return A.section(tone, `<div class="mw">${textCol}</div>`, { pad: v === 'banner' ? 'xl' : 'l', bg, rule: !d.videoUrl });
